pragma solidity ^0.4.16;

// https://github.com/ethereum/EIPs/issues/20
contract ERC20 {
    function totalSupply() constant returns (uint totalSupply);
    function balanceOf(address _owner) constant returns (uint balance);
    function transfer(address _to, uint _value) returns (bool success);
    function transferFrom(address _from, address _to, uint _value) returns (bool success);
    function approve(address _spender, uint _value) returns (bool success);
    function allowance(address _owner, address _spender) constant returns (uint remaining);
    event Transfer(address indexed _from, address indexed _to, uint _value);
    event Approval(address indexed _owner, address indexed _spender, uint _value);
}

contract PriceRace{
    address private admin;
    uint public rate;
    ERC20 asset;

    function PriceRace(uint _price, ERC20 _token)
        public 
    {
        admin = msg.sender;
        rate = _price;
        asset = _token;
    }

    // If the admin sees someone calls purchase
    // he can call updateRate to set a new rate
    // If his transaction is mined first, he can
    // receive more tokens than excepted by the new buyer
    function purchase(uint new_rate) payable
        public
    {
        require(msg.value >= rate);

        // we assume that the PriceRace contract
        // has enough allowance
        asset.transferFrom(msg.sender, admin, rate);

        rate = new_rate;
        admin = msg.sender;
    }

    function updateRate(uint new_rate){
        require(msg.sender == admin);
        rate = new_rate; 
    }

}
